<%= tag.div \
      id: dom_id(card, "bubble"),
      hidden: true,
      class: "bubble",
      data: {
        controller: "bubble",
        action: "turbo:morph-element->bubble#update:self",
        bubble_entropy_value: entropy_bubble_options_for(card).to_json
      } do %>

  <svg viewBox="0 0 200 100">
    <path id="<%= dom_id(card, "bubble-top-half") %>" fill="transparent" d="M 20,100 A 80,80 0 0,1 180,100"/>
    <text text-anchor="middle" fill="currentColor">
      <textPath href="#<%= dom_id(card, "bubble-top-half") %>" startOffset="50%" dominant-baseline="middle" data-bubble-target="top"></textPath>
    </text>
  </svg>

  <span class="bubble__number" data-bubble-target="center"></span>

  <svg viewBox="0 0 200 100">
    <path id="<%= dom_id(card, "bubble-bottom-half") %>" d="M 20,0 A 80,80 0 0,0 180,0" fill="transparent"/>
    <text text-anchor="middle" fill="currentColor">
      <textPath href="#<%= dom_id(card, "bubble-bottom-half") %>" startOffset="50%" dominant-baseline="middle" data-bubble-target="bottom"></textPath>
    </text>
  </svg>
<% end %>
=====bubble css=====
@layer components {
  .bubble {
    --bubble-color: var(--card-color, oklch(var(--lch-blue-medium)));
    --bubble-number-max: 26px;
    --bubble-shape: 54% 46% 61% 39% / 57% 49% 51% 43%;
    --bubble-rotate: 0deg;
    --bubble-size-default: 4rem;

    block-size: var(--bubble-size, var(--bubble-size-default));
    color: var(--card-content-color);
    container-type: inline-size;
    font-size: 1.4rem;
    font-weight: bold;
    inline-size: var(--bubble-size, var(--bubble-size-default));
    inset-block-start: 20%;
    padding: 0.5cqi;
    position: absolute;
    z-index: 1;

    &:before {
      background: radial-gradient(
        color-mix(in srgb, var(--bubble-color) 8%, var(--color-canvas)) 50%,
        color-mix(in srgb, var(--bubble-color) 48%, var(--color-canvas)) 100%
      );
      border-radius: var(--bubble-shape);
      content: "";
      inset: 0;
      position: absolute;
      transform: rotate(var(--bubble-rotate));
      z-index: -1;
    }

    @media (any-hover: hover) {
      &:hover:before {
        animation: wobble 1200ms;
      }
    }

    svg {
      display: block;
      letter-spacing: 0.2ch;
      text-transform: uppercase;
    }
  }

  .bubble__number {
    display: grid;
    font-size: clamp(10px, 50cqi, var(--bubble-number-max)); /* FF bug: https://app.fizzy.do/5986089/boards/2/cards/1373 */
    font-weight: 900;
    inset: 0;
    place-content: center;
    position: absolute;
    text-align: center;
  }
}
=====bridge helper=====
module BridgeHelper
  def bridge_icon(name)
    asset_url("#{name}.svg")
  end

  def bridged_button_to_board(board)
    link_to "Go to #{board.name}", board, hidden: true, data: {
      bridge__buttons_target: "button",
      bridge_icon_url: bridge_icon("board"),
      bridge_title: "Go to #{board.name}"
    }
  end

  def bridged_share_url_button(description = nil)
    tag.button "Share", hidden: true, data: {
      controller: "bridge--share",
      action: "bridge--share#shareUrl",
      bridge__overflow_menu_target: "item",
      bridge_title: "Share",
      bridge_share_description: description
    }
  end

  def bridge_share_card_description(card)
    date_added = card.created_at.strftime("%b %e")
    date_updated = card.last_active_at.strftime("%b %e")
    author = card.creator.familiar_name
    assignees = card.assignees.any? ? "assigned to #{card.assignees.map { |assignee| h assignee.familiar_name }.to_sentence}" : "not assigned"
    "Added #{date_added} by #{author} and #{assignees}. Updated #{date_updated}"
  end

  def bridge_share_board_description(board)
    count_open = board.cards.active.count
    count_in_stream = board.cards.awaiting_triage.count
    "#{count_open} open cards, #{count_in_stream} in MAYBE?"
  end
end
"
}

