class Card::StallableTest < ActiveSupport::TestCase
  test "uses the board's auto-close period override for the burst window" do
    card = cards(:buy_domain)
    card.board.entropy.update!(auto_postpone_period: 7.days)

    travel_to 2.days.ago { card.comments.create!(creator: users(:david), body: "One") }
    travel_to 1.day.ago { card.comments.create!(creator: users(:jz), body: "Two") }
    travel_to Time.current { card.comments.create!(creator: users(:kevin), body: "Three") }

    assert card.reload.burst?
  end

  test "does not burst outside the board's auto-close period override" do
    card = cards(:buy_domain)
    card.board.entropy.update!(auto_postpone_period: 7.days)

    travel_to 5.days.ago { card.comments.create!(creator: users(:david), body: "One") }
    travel_to 3.days.ago { card.comments.create!(creator: users(:jz), body: "Two") }
    travel_to Time.current { card.comments.create!(creator: users(:kevin), body: "Three") }

    assert_not card.reload.burst?
  end
end
